fn all_unplayable_curses_have_cost_neg_one() {
    let unplayables = [
        specs::ascenders_bane(),
        specs::bad_luck(),
        specs::clumsy(),
        specs::curse_of_the_bell(),
        specs::debt(),
        specs::decay(),
        specs::doubt(),
        specs::folly(),
        specs::greed(),
        specs::guilty(),
        specs::injury(),
        specs::normality(),
        specs::pain(),
        specs::parasite(),
        specs::poor_sleep(),
        specs::regret(),
        specs::shame(),
        specs::writhe(),
    ];
    for s in unplayables {
        assert_eq!(s.cost, -1, "{:?} should have cost -1", s.id);
        assert!(
            s.keywords
                .contains(super::super::types::CardKeywords::UNPLAYABLE),
            "{:?} should be UNPLAYABLE",
            s.id
        );
    }
}

/// The ETERNAL keyword is what makes a card non-removable, so the set of
/// cards carrying it IS the removal filter — `card_is_removable_csharp`
/// reads nothing else, and `RunState::removal_offer_order` reads that.
///
/// Four of these were missing it (BadLuck, CurseOfTheBell, Enthralled,
/// Folly), so the engine offered them for removal and the PPO bridges
/// produced live `remove:ENTHRALLED` shop picks that no
/// `CardSelectCmd.FromDeckForRemoval` screen can satisfy. Pinned as an
/// exact set rather than per-card asserts: a card GAINING the keyword
/// wrongly is as broken as one missing it, and only an exact comparison
/// catches both.
///
/// Source of truth: `grep -l "CardKeyword.Eternal"` over
/// `../sts2-wiki/decompiled/v0.107.1/MegaCrit.Sts2.Core.Models.Cards/`.
#[test]
fn eternal_is_exactly_the_seven_cards_c_sharp_marks_eternal() {
    install_pool();
    let mut eternal: Vec<&'static str> = sts2_core::cards::CardId::all()
        .iter()
        .copied()
        .filter(|&c| !super::super::spec_index::card_is_removable_csharp(c))
        .map(sts2_core::cards::CardId::to_python_name)
        .collect();
    eternal.sort_unstable();
    assert_eq!(
        eternal,
        vec![
            "ASCENDERS_BANE",
            "BAD_LUCK",
            "CURSE_OF_THE_BELL",
            "ENTHRALLED",
            "FOLLY",
            "FORBIDDEN_GRIMOIRE",
            "GREED",
        ],
    );
}

/// Basic Strike/Defend are REMOVABLE. The inverse of the pin above, and it
/// needs saying out loud: a legacy `CardId::is_removable` excluded them, the
/// comment on it claimed v0.107.1 did too, and both PPO bridges hand-copied
/// that claim — which withheld the standard Strike-thinning line from every
/// deployed champion. `WoodCarvings.cs:39` tests `Rarity == Basic &&
/// IsRemovable`, which only makes sense because basics pass.
#[test]
fn basic_strike_and_defend_are_removable() {
    install_pool();
    for id in [
        CardId::StrikeIronclad,
        CardId::DefendIronclad,
        CardId::StrikeSilent,
        CardId::DefendSilent,
    ] {
        assert!(
            super::super::spec_index::card_is_removable_csharp(id),
            "{id:?} must be removable — C# gates only on the Eternal keyword"
        );
    }
}

/// The removability rule reads the card's LIVE keyword set, not its class's.
/// `TezcatarasEmber.OnEnchant` calls `Card.AddKeyword(CardKeyword.Eternal)`
/// (`TezcatarasEmber.cs:18`), and `NutritiousSoup` hands that enchantment to
/// every basic Strike in the deck — so after picking up Nutritious Soup, a
/// Strike is non-removable in the real game.
///
/// This is why [`super::super::spec_index::card_is_removable_instance`] takes
/// a `Card`. The id-only form cannot see it, and because
/// `RunState::removal_offer_order` indices are positional, one wrongly
/// offered Strike shifts every later removal pick — the exact shape of the
/// lockstep desyncs `sts2-rs-RP22` chased.
#[test]
fn tezcataras_ember_makes_an_otherwise_removable_card_eternal() {
    use sts2_core::cards::{Card, EnchantmentId};
    install_pool();
    let removable = super::super::spec_index::card_is_removable_instance;

    let mut strike = Card {
        card_id: CardId::StrikeIronclad,
        ..Card::pod_defaults()
    };
    assert!(removable(&strike), "a plain basic Strike is removable");

    strike.set_enchantment(EnchantmentId::TezcatarasEmber, 1);
    assert!(
        !removable(&strike),
        "TezcatarasEmber adds Eternal, so IsRemovable is false"
    );

    // A different enchantment must not leak into the removal gate.
    let mut goopy = Card {
        card_id: CardId::StrikeIronclad,
        ..Card::pod_defaults()
    };
    goopy.set_enchantment(EnchantmentId::Goopy, 1);
    assert!(removable(&goopy), "Goopy adds Exhaust, not Eternal");
}

/// The id-only [`super::super::spec_index::card_is_removable_csharp`] is the
/// wire/bridge approximation and is deliberately OPTIMISTIC: it agrees with
/// the instance form on every unenchanted card, and cannot see an Ember. The
/// test exists so that difference is a recorded decision, not a surprise.
#[test]
fn the_id_only_predicate_agrees_except_on_enchantments() {
    use sts2_core::cards::{Card, EnchantmentId};
    install_pool();
    for id in CardId::all().iter().copied() {
        let card = Card {
            card_id: id,
            ..Card::pod_defaults()
        };
        assert_eq!(
            super::super::spec_index::card_is_removable_csharp(id),
            super::super::spec_index::card_is_removable_instance(&card),
            "{id:?}: the two removability predicates disagree unenchanted"
        );
    }
    let mut embered = Card {
        card_id: CardId::StrikeIronclad,
        ..Card::pod_defaults()
    };
    embered.set_enchantment(EnchantmentId::TezcatarasEmber, 1);
    assert!(
        super::super::spec_index::card_is_removable_csharp(embered.card_id)
            && !super::super::spec_index::card_is_removable_instance(&embered),
        "the id-only form is the one that over-reports"
    );
}

// ---- Deep pin: Ascender's Bane unplayable curse ----
/// Ascender's Bane is the canonical Ascension starter curse. Pin locks
/// (a) cost == -1, (b) UNPLAYABLE + ETHEREAL + ETERNAL keywords, (c)
/// Curse type, (d) handler is a registered no-op (engine rejects play;
/// if somehow dispatched, returns Resolved without side effects).
/// C# `AscendersBane.cs` `CanonicalKeywords = [Eternal, Unplayable,
/// Ethereal]`; ETERNAL is representational only (bead `sts2-rs-8ixr6`).
#[test]
fn ascenders_bane_deep_pin_unplayable_curse() {
    install_pool();
    let s = specs::ascenders_bane();
    assert_eq!(s.cost, -1);
    assert_eq!(
        s.card_type,
        sts2_core::cards::CardType::Curse,
        "card_type Curse"
    );
    assert!(s
        .keywords
        .contains(super::super::types::CardKeywords::UNPLAYABLE));
    assert!(s
        .keywords
        .contains(super::super::types::CardKeywords::ETHEREAL));
    assert!(
        s.keywords
            .contains(super::super::types::CardKeywords::ETERNAL),
        "AscendersBane must carry the ETERNAL keyword (C# CanonicalKeywords)"
    );

    // Verify handler is registered and is a no-op on direct invocation.
    let f = lookup(CardId::AscendersBane).expect("registered");
    let mut state = CombatState::default();
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    assert!(state.creatures.is_empty());
    assert_eq!(state.player.block, 0);
}

