/// Decay — end-of-turn 2 damage trigger (the trigger lives in
/// combat_loop). Spec is UNPLAYABLE; handler is a marker.
#[test]
fn decay_unplayable_with_eot_trigger_marker() {
    install_pool();
    let s = specs::decay();
    assert!(s
        .keywords
        .contains(super::super::types::CardKeywords::UNPLAYABLE));
    // Handler is a marker — confirm registration + Resolved return.
    let f = lookup(CardId::Decay).expect("registered");
    let mut state = CombatState::default();
    assert_eq!(f(&mut state, None), EffectResult::Resolved);
}
